#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    vector<long long> a((size_t)n * n);
    for (auto &x : a) scanf("%lld", &x);
    // Track where original cell (0,0) goes (origin) and where unit row/col steps go (dr, dc).
    int o0 = 0, o1 = 0, r0 = 1, r1 = 0, c0 = 0, c1 = 1;
    for (int t = 0; t < q; t++) {
        int k;
        scanf("%d", &k);
        if (k == 0) {
            int t0 = o1, t1 = n - 1 - o0; o0 = t0; o1 = t1;
            t0 = r1; t1 = -r0; r0 = t0; r1 = t1;
            t0 = c1; t1 = -c0; c0 = t0; c1 = t1;
        } else if (k == 1) {
            swap(o0, o1); swap(r0, r1); swap(c0, c1);
        } else {
            int t0 = n - 1 - o1, t1 = n - 1 - o0; o0 = t0; o1 = t1;
            t0 = -r1; t1 = -r0; r0 = t0; r1 = t1;
            t0 = -c1; t1 = -c0; c0 = t0; c1 = t1;
        }
    }
    vector<long long> res((size_t)n * n);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            res[(size_t)(o0 + i * r0 + j * c0) * n + (o1 + i * r1 + j * c1)] = a[(size_t)i * n + j];
    string out;
    char buf[24];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int len = snprintf(buf, sizeof buf, "%lld", res[(size_t)i * n + j]);
            out.append(buf, len);
            out += j + 1 < n ? ' ' : '\n';
        }
    }
    fputs(out.c_str(), stdout);
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), q = nextInt();
        long[] a = new long[n * n];
        for (int i = 0; i < n * n; i++) a[i] = nextLong();
        // Track where original cell (0,0) goes (origin) and where unit row/col steps go (dr, dc).
        int o0 = 0, o1 = 0, r0 = 1, r1 = 0, c0 = 0, c1 = 1, t0, t1;
        for (int t = 0; t < q; t++) {
            int k = nextInt();
            if (k == 0) {
                t0 = o1; t1 = n - 1 - o0; o0 = t0; o1 = t1;
                t0 = r1; t1 = -r0; r0 = t0; r1 = t1;
                t0 = c1; t1 = -c0; c0 = t0; c1 = t1;
            } else if (k == 1) {
                t0 = o0; o0 = o1; o1 = t0;
                t0 = r0; r0 = r1; r1 = t0;
                t0 = c0; c0 = c1; c1 = t0;
            } else {
                t0 = n - 1 - o1; t1 = n - 1 - o0; o0 = t0; o1 = t1;
                t0 = -r1; t1 = -r0; r0 = t0; r1 = t1;
                t0 = -c1; t1 = -c0; c0 = t0; c1 = t1;
            }
        }
        long[] res = new long[n * n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                res[(o0 + i * r0 + j * c0) * n + (o1 + i * r1 + j * c1)] = a[i * n + j];
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                sb.append(res[i * n + j]);
                sb.append(j + 1 < n ? ' ' : '\n');
            }
        }
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        pw.print(sb);
        pw.flush();
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	n, q := readInt(), readInt()
	a := make([]int, n*n)
	for i := range a {
		a[i] = readInt()
	}
	// Track where original cell (0,0) goes (origin) and where unit row/col steps go (dr, dc).
	o0, o1, r0, r1, c0, c1 := 0, 0, 1, 0, 0, 1
	for t := 0; t < q; t++ {
		switch readInt() {
		case 0:
			o0, o1 = o1, n-1-o0
			r0, r1 = r1, -r0
			c0, c1 = c1, -c0
		case 1:
			o0, o1 = o1, o0
			r0, r1 = r1, r0
			c0, c1 = c1, c0
		default:
			o0, o1 = n-1-o1, n-1-o0
			r0, r1 = -r1, -r0
			c0, c1 = -c1, -c0
		}
	}
	res := make([]int, n*n)
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			res[(o0+i*r0+j*c0)*n+(o1+i*r1+j*c1)] = a[i*n+j]
		}
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	buf := make([]byte, 0, 24)
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			buf = strconv.AppendInt(buf[:0], int64(res[i*n+j]), 10)
			w.Write(buf)
			if j+1 < n {
				w.WriteByte(' ')
			} else {
				w.WriteByte('\n')
			}
		}
	}
}
